package org.example.historyinaglimpse;
import com.fasterxml.jackson.databind.JsonNode;
import javafx.animation.*;import javafx.application.Platform;import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.image.*;import javafx.scene.layout.*;import javafx.util.Duration;
/** Fossil relatives and living branches, never a chain of direct ancestors. */
final class EvolutionPane extends BorderPane implements AutoCloseable {
 private static final String[] NAMES={"Moeritherium · Eocene relative","Gomphotherium · Miocene relative","American mastodon · extinct branch","Woolly mammoth · extinct branch","African savanna elephant · living","Asian elephant · living"};
 private final JsonNode taxa;private final ImageView animal=new ImageView();private final Label name=new Label();private final Timeline clock;private int index;private Image atlas;private FadeTransition fade;private boolean closed;
 EvolutionPane(String id,JsonNode settings){taxa=settings.path("taxa");StackPane stage=new StackPane(animal);stage.setMinSize(0,0);stage.setStyle("-fx-background-color:#eee6d4;");animal.setPreserveRatio(true);animal.setSmooth(true);animal.fitWidthProperty().bind(stage.widthProperty().subtract(36));animal.fitHeightProperty().bind(stage.heightProperty().subtract(36));setCenter(stage);Button previous=new Button("Previous"),next=new Button("Next"),play=new Button("Play");previous.setOnAction(e->select((index+5)%6));next.setOnAction(e->select((index+1)%6));clock=new Timeline(new KeyFrame(Duration.seconds(5),e->select((index+1)%6)));clock.setCycleCount(Animation.INDEFINITE);play.setOnAction(e->{if(clock.getStatus()==Animation.Status.RUNNING){pause();play.setText("Play");}else{clock.play();play.setText("Pause");}});VBox controls=new VBox(8,name,new HBox(8,previous,play,next),new Label("Related branches, not a sequence of direct ancestors."),familyTree());controls.setPadding(new Insets(12));controls.setStyle("-fx-font-size:13px;");setBottom(controls);BatchMedia.image(id,"background").whenComplete((image,error)->Platform.runLater(()->{if(closed)return;if(error!=null){name.setText("Could not load the elephant illustrations.");return;}atlas=image;animal.setImage(atlas);select(0);}));}
 private void select(int value){index=value;name.setText(NAMES[index]);if(atlas!=null){JsonNode taxon=taxa.path(index);if(taxon.has("name"))name.setText(taxon.path("name").asText());double w=atlas.getWidth()/3,h=atlas.getHeight()/2;animal.setViewport(taxon.has("x")?new Rectangle2D(taxon.path("x").asDouble(),taxon.path("y").asDouble(),taxon.path("width").asDouble(),taxon.path("height").asDouble()):new Rectangle2D(index%3*w,index/3*h,w,h));if(fade!=null)fade.stop();fade=new FadeTransition(Duration.millis(550),animal);fade.setFromValue(.25);fade.setToValue(1);fade.play();}}
 private javafx.scene.Node familyTree(){
  javafx.scene.canvas.Canvas tree=new javafx.scene.canvas.Canvas(500,130);var g=tree.getGraphicsContext2D();g.setStroke(javafx.scene.paint.Color.web("#52736b"));g.setLineWidth(2);g.strokeLine(12,65,85,65);g.strokeLine(85,18,85,112);g.strokeLine(85,18,150,18);g.strokeLine(85,80,200,80);g.strokeLine(200,55,200,110);g.strokeLine(200,55,270,55);g.strokeLine(200,110,270,110);g.strokeLine(85,112,145,112);
  g.setFill(javafx.scene.paint.Color.web("#2c4a43"));g.setFont(javafx.scene.text.Font.font(12));g.fillText("Mastodon family (extinct)",155,22);g.fillText("African elephants",275,59);g.fillText("Asian elephants + mammoths",275,114);g.fillText("Other extinct branches",150,126);g.fillText("Simplified family relationships · branch lengths do not show time",5,43);
  StackPane box=new StackPane(tree);box.setMinWidth(0);box.widthProperty().addListener((o,a,b)->{double scale=Math.min(1,b.doubleValue()/500);tree.setScaleX(scale);tree.setScaleY(scale);box.setPrefHeight(130*scale);});return box;
 }
 void pause(){clock.pause();}public void close(){closed=true;clock.stop();if(fade!=null)fade.stop();}
}
